export const bundledWarriors = [{"file": "artofcorewar.red", "source": ";redcode-94nop verbose\n;name The Art of CoreWar\n;author Fluffy/Sascha Zapf\n;strategy qBob -> paper\n;date Sat Jun 23 11:33:26 UTC 2007\n;assert CORESIZE == 8000\n\n        ORG     qBob\n\n; --=| qBob |-----------------------------------------------------\n;\n; New quickscanner completely written from scratch.\n;\n; Scanned locations (relative to start of warrior):\n;         336,  436,  536,  686,  786,  893, 1143, 1536, 1643, 1786, 1893,\n;        2093, 2393, 2536, 2786, 3036, 3393, 3536, 4036, 4193, 4293, 4393,\n;        4543, 4643, 5036, 5286, 5393, 5643, 5786, 6036, 6236, 6393, 6536,\n;        6643, 6893, 7393, 7536, 7893\n;\n; Requirements:\n;        qTab1@42, qTab2@94, qFound@36\n\n        ; Constants for qBob chosen to have at least a minimal distance\n        ; of 100 between all scanned locations.\n\n        qA      EQU     1496\n        qB      EQU     2746\n        qC      EQU     4995\n        qD      EQU      750\n        qE      EQU      494\n        qF      EQU      644\n        qG      EQU     5694\n        qH      EQU     5550\n        qI      EQU     5192\n\n        qHop    EQU     3857\n\n        ; --=| qG mutation |------------------------------------\n\n        ; sne.i qFound+qG*qD,            qFound+qG*qD+qHop\n        ; seq.i < (qTab2-1),             qFound+(qG-1)*qD+qHop\n\n        qOff01  EQU     ((qG * qD) % CORESIZE)\n        qOff02  EQU     (((qG-1) * qD) % CORESIZE)\n\nqBob    sne.i   qFound + qOff01,                qFound + qOff01 + qHop\n        seq.i   < (qTab2 - 1),                  qFound + qOff02 + qHop\n        jmp     qDec0,                          { qDec0\n\n        ; --=| qI mutation |-----------------------------------\n\n        ; sne.i qFound+qI*qD,            qFound+qI*qD+qHop\n        ; seq.i < (qTab2+1),             qFound+(qI-1)*qD+qHop\n\n        qOff03  EQU     ((qI * qD) % CORESIZE)\n        qOff04  EQU     (((qI-1) * qD) % CORESIZE)\n\n        sne.i   qFound + qOff03,                qFound + qOff03 + qHop\n        seq.i   < (qTab2 + 1),                  qFound + qOff04 + qHop\n        jmp     qDec0,                          } qDec0\n\n        ; --=| qB mutation |------------------------------\n\n        ; sne.i qFound+qB*qH,            qFound+qB*qH+qHop\n        ; seq.i < (qTab1-1),             qFound+(qB-1)*qH+qHop\n\n        qOff05  EQU     ((qB * qH) % CORESIZE)\n        qOff06  EQU     (((qB-1) * qH) % CORESIZE)\n\n        sne.i   qFound + qOff05,                qFound + qOff05 + qHop\n        seq.i   < (qTab1 - 1),                  qFound + qOff06 + qHop\n        jmp     qDec0,                          < qDec1\n\n        ; --=| qF mutation |---------------------------------\n\n        ; sne.i qFound+qF*qH,            qFound+qF*qH+qHop\n        ; seq.i < (qTab1+1),             qFound+(qF-1)*qH+qHop\n\n        qOff07  EQU     ((qF * qH) % CORESIZE)\n        qOff08  EQU     (((qF-1) * qH) % CORESIZE)\n\n        sne.i   qFound + qOff07,                qFound + qOff07 + qHop\n        seq.i   < (qTab1 + 1),                  qFound + qOff08 + qHop\n        jmp     qDec0,                          > qDec1\n\n        ; --=| qC mutation |--------------------------------\n\n        ; sne.i qFound+qC*qD*qH,         qFound+qC*qD*qH+qHop\n        ; seq.i { qTab1,                 qFound+(qC-1)*qD*qH+qHop\n\n        qOff09  EQU     ((((qC * qD) % CORESIZE) * qH) % CORESIZE)\n        qOff10  EQU     (((((qC-1) * qD) % CORESIZE) * qH) % CORESIZE)\n\n        sne.i   qFound + qOff09,                qFound + qOff09 + qHop\n        seq.i   { qTab1,                        qFound + qOff10 + qHop\n        jmp     qDec1,                          } qFound + qOff09 - 4\n\n        ; --=| qE mutation |---------------------------------\n\n        ; sne.i qFound+qE*qD*qH,         qFound+qE*qD*qH+qHop\n        ; seq.i { (qTab1 + 1),           qFound+(qE-1)*qD*qH+qHop\n\n        qOff11  EQU     ((((qE * qD) % CORESIZE) * qH) % CORESIZE)\n        qOff12  EQU     (((((qE-1) * qD) % CORESIZE) * qH) % CORESIZE)\n\n        sne.i   qFound + qOff11,                qFound + qOff11 + qHop\n        seq.i   { (qTab1 + 1),                  qFound + qOff12 + qHop\n        jmp     qDec1,                          } qDec1\n\n        ; --=| qA mutation |----------------------------------\n\n        ; sne.i qFound+qA*qD*qH,         qFound+qA*qD*qH+qHop\n        ; seq.i { (qTab1 - 1),           qFound+(qA-1)*qD*qH+qHop\n\n        qOff13  EQU     ((((qA * qD) % CORESIZE) * qH) % CORESIZE)\n        qOff14  EQU     (((((qA-1) * qD) % CORESIZE) * qH) % CORESIZE)\n\n        sne.i   qFound + qOff13,                qFound + qOff13 + qHop\n        seq.i   { (qTab1 - 1),                  qFound + qOff14 + qHop\n        jmp     qDec1,                          { qDec1\n\n        ; --=| qH mutation with a trick |----------------------\n\n        ; sne.i qFound+qD*qH,            qFound+qD*qH+qHop\n        ; seq.i qFound+qD*(qH-1),        < qTab2\n\n        qOff15  EQU     ((qD * qH) % CORESIZE)\n        qOff16  EQU     ((qD * (qH-1)) % CORESIZE)\n\n        sne.i   qFound + qOff15,                qFound + qOff15 + qHop\n        seq.i   qFound + qOff16,                < qTab2\n        jmp     qDec0,                          } qFound + qOff15 - 4\n\n        ; --=| free scan |----------------------------------\n\n        qOff17  EQU     qFree\n\n        seq.i   qFound + qOff17,                qFound + qOff17 + qHop\n        jmp     qSelect,                        } qFound + qOff17 - 4\n\n        ; --=| fast scan |-------------------------------------\n\n        qOff18  EQU     qD\n\n        seq.i   qFound + qOff18,                qFound + qOff18 + qHop\n        jmp     qSetup,                         } qFound + qOff18 - 4\n\n        ; --=| fallthrough scan |------------------------\n\n        ; sne.i qFound+(qC-1)*qD*(qH-1), qFound+(qC-1)*qD*(qH-1)\n\n        qOff19  EQU     (((((qC-1) * qD) % CORESIZE) * (qH-1)) % CORESIZE)\n\n        sne.i   qFound + qOff19,                qFound + qOff19 + qHop\n        jmz.f   boot,                           qFound + qOff19 + qHop + 1\n\n        ; --=| decoder |-------------------------------------\n\nqDec1   mul.ab  qTab1,                          qTab1\nqDec0   mul.b   qTab2,                          @ qDec1\nqSetup  mov.b   @ qDec1,                        qFound\n\n        ; --=| choose between the two possible locations |-------------\n\nqSelect sne.i   qEmpty,                         @ qFound\n        add.ab  # qHop,                         qFound\n\n        ; --=| bombing engine |-----------------------------\n\n        ; Although possible the engine from Tornado has been proven to be less\n        ; effective here.\n\n        qOffset EQU      -80\n        qTimes  EQU       19\n        qStep   EQU        6\n        qFree   EQU      400\n\nqAttack mov.i   qBomb,                          @ qFound\nqFound  mov.i   qBomb,                          } qFree\n        add.ab  # qStep,                        qFound\n        djn     qAttack,                        # qTimes\n\n        ; --=| start warrior |---------------------------------\n\n        jmp     boot\n\nqEmpty  dat.f   0,                              0\n\n        ; --=| decoder table |-------------------------------\n\n        dat.f   qA,                             qB\nqTab1   dat.f   qC,                             qD\n        dat.f   qE,                             qF\n\nqBomb   dat.f   > qOffset,                      > 1\n\n; --=| some empty space between qBob and paper code |---------------\n\n        pOffset EQU       40\n\nFOR pOffset\n        dat.f   0,                              0\nROF\n\n; --=| paper |------------------------------------------------\n\n        ; Heavily optimized paper constants.\n\n        pStep1  EQU      939\n        pStep2  EQU     1928\n        pStep3  EQU      241\n\n        iStep   EQU     6332\n        x       EQU      174\n        y       EQU     6853\n\n        ; Paper structure taken from nPaper II after testing several dozens\n        ; of different structures.\n\nsilk1   spl     @ silk1 + 8,                    } pStep1\n        mov.i   } silk1,                        > silk1\n\nsilk2   spl     @ silk2,                        > pStep2\n        mov.i   } silk2,                        > silk2\n\n        ; Attack code taken from Harmless Fluffy Bunny and The Human Machine.\n\n        mov.i   # iStep,                        { 1\n        mov.i   x,                              } y\n\n        mov.i   { silk2,                        < silk3\nsilk3   jmz.a   @ silk3,                        pStep3\n\nFOR (40 - pOffset)\n        dat.f   0,                              0\nROF\n\n; --=| boot |--------------------------------------------------\n\n        ; Heavily optimized boot constants.\n\n        awayOff EQU     4425\n        pAway1  EQU     (awayOff + 5199)\n        pAway2  EQU     (awayOff + 4078)\n        decoy   EQU     4856\n\n        ; Create 8 processes.\n\nboot    spl     } 1,                            < qG\nqTab2   spl     0,                              < qH\n        spl     1,                              < qI\n\n        ; Create and start two copies of the paper.\n        ; Idea taken from paper(paper(paper(clear))).\n\n        mov.i   { silk1,                        { pBoot1\npBoot1  spl     pAway1,                         { pAway2 + pBoot2\n\n        mov.i   } pBoot1,                       > pBoot1\npBoot2  djn.f   pAway2,                         { decoy\n\n        END\n\n"}, {"file": "excalibur.red", "source": ";redcode-94nop\n;name Excalibur\n;author inversed\n;strategy Completely reworked Agony II\n;assert CORESIZE == 8000\n\nhop     equ     8\nwlen    equ     16\nstep    equ     3147\nsofs    equ     scan\nstream  equ     (-344)\nssafe   equ     27\ncsafe   equ     10\ndsafe   equ     3\nbd      equ     1423\norg     bp-11\n\n        ;; Decoy\nfor     6\n        spl.a   # 1         ,     1\n        spl.b   # 1         ,     1\n        spl.ab  # 1         ,     1\n        spl.ba  # 1         ,     1\n        spl.f   # 1         ,     1\n        spl.x   # 1         ,     1\n        spl.i   # 1         ,     1\n        spl.i   $ 1         ,     1\nrof\n        spl.a   # 1         ,     1\n        spl.b   # 1         ,     1\n        spl.ab  # 1         ,     1\n\n        ;; Boot\n        mov     > 9         ,   } 9             ; mirror\n        mov     > 8         ,   } 8             ;\n        mov     > 7         ,   } 7             ;\nfor     3\n        dat       0         ,     0\nrof\nfor     11\n        mov     > bp        ,   } bp\nrof\nbp      spl       scan+bd   ,     scan\nfor     5\n        mov     > bp        ,   } bp\nrof\n        dat     } bp        ,   } bp\n        mov     > 1         ,   } 1             ; mirror\n\n        ;; Scanner\nscan    sub     * y         ,   @ x\nptr     sne       sofs-hop  ,     sofs\n        sub     * y         ,     ptr\nx       seq     * ptr       ,   @ ptr\n        slt     # ssafe     ,   @ x\n        djn.f     scan      ,   < scan+stream\nbptr    mov.b   @ x         ,   # 0\n        mov     # wlen/2    ,     count\nwipe    mov       inc       ,   < bptr\ny       mov       inc       ,   < bptr\ncount   djn       wipe      ,   # 0\n        jmz.a     scan      ,     scan-1\ninc     spl     #-step      ,    -step\nclear   mov       kill      ,   > y\n        djn.f     clear     ,   { y\nkill    dat       dsafe     ,     csafe\n\n        mov       4         ,   <-2             ; mirror\n        mov       3         ,   <-3             ;\n        djn      -2         ,   # 0             ;\n        jmz.a    -11        ,    -12            ;\n        spl     #-step      ,    -step          ;\n        mov       2         ,   >-4             ;\n        djn.f    -1         ,   {-5             ;\n        dat       dsafe     ,     csafe         ;\n\n"}, {"file": "forgottenloreii.red", "source": ";redcode-94nop quiet\n;assert CORESIZE==8000\n;name Forgotten Lore II\n;author David Moore\n;strategy Scanning vamp which multitasks between two forms of attack.\n;strategy First, DJNs are delivered throughout the core in an effort\n;strategy to immobilize typical stones and core clears.\n;strategy Second, scan for anything nonzero and drop a JMP on it.\n;strategy The JMP points to a trap.\n;strategy Next, we wipe the core with SPLs, starting with the trap.\n;strategy Finally, the SPL clear is converted to a DAT clear.\n;strategy Version II strategy: Instead of using pspace to switch\n;strategy between a vamp and a 1-shot SPL/DAT clear, combine them into\n;strategy the same warrior. Rather than jumping to the SPL clear\n;strategy as soon as something is scanned, wait until we've actually\n;strategy captured a process.\n\nfirst equ (-117)\ntptr equ 218  ; position of pointer to trap, relative to bite.\n\nflag  dat 0, 0  ; When this gets hit, go to the core clear.\nbite  jmp @tptr-first, first  ; This is used to send opponents to trap.\n\n; Note the use of @ indirection (in the JMP attack, in the line above)\n; which helps to protect the trap. This helps when one of the JMPs\n; lands next to something like MOV.I >-1, }-1 in the opponent's code.\n; Processes that are already in the trap won't get overwritten\n; by such a MOV. Only the pointer to the trap gets overwritten.\n;\n; After the initial phase (in which the JMPs are deployed),\n; a core-clear will start.\n; When the pointer to the trap gets overwritten by the core clear,\n; it will then point to a second trap. In case the original trap\n; is damaged, the core clear provides a new one.\n; Another benefit of @ indirection: When silks get hit with a JMP\n; and they copy the JMP to later generations, they are less likely\n; to jump into my own code with @ than with $ (direct).\n;\n; The close proximity of \"flag\" to \"bite\" is intended as an\n; anti-silk measure. If a silk hits the JMP at bite,\n; then chances are pretty good that it hits flag as well.\n; This allows us to skip the vamp phase (which is no longer\n; effective due to the damaged JMP) and proceed directly\n; to the SPL/DAT clear.\n\n   for 19\n      dat 0,0\n   rof\n\nboot  mov.x #(trap-bite)-(tptr+1), bite+tptr+1  ; Copy a pointer to trap\n      mov.x #(trap-bite)-(tptr), }bp  ; plus extras in case of +1/-1 hit\n      mov >tsrc, >tdest;  Create decoy & 2nd trap.\n      mov -5, }lj  ; Hide boot code.\n\nloop  sub.x #-bite-1, bite\n      mov  b2, *bite\nlj    jmz.f boot, <bite ; Scan at a rate of .33c (after boot).\n      mov  @-2, @bite  ; Found something; let's hit it.\n      jmz.f loop, flag  ; Stop if opponent caught already.\ntdest jmp  clear, <6619  ; Go to SPL/DAT core clear.\n\n   for 16\n      dat 0,0\n   rof\n\n; This core clear can often beat 3 point imps (3 * 2667) without the\n; need to meet them at the gate.\n; The gate stops imps of the form MOV.I #1143, *0.\n; If an imp of the form MOV.I #2, 1143 reaches the gate, the core clear\n; will self destruct.\n\ngate  dat 25, 3987\n      dat 0, 0\n      dat <2667, 9\nclear spl #11, {6568  ; This will become spl #11, {1\n      mov  -1, >gate  ; Then this will become mov -2, >gate\n      mov *-1, }gate\n      jmp  -2, <-3\n\n   for 22\n      dat 0,0\n   rof\n\nb2    djn.f #1, 1   ; These get thrown around at .33c.\n\n; Using DJN.F #1, 1 is intended to disable self-splitting loops\n; of the form:\n; ;    SPL 0, 0\n; ;    MOV\n; ;    DJN.F -1, > X\n\n   for 17\n      dat 0,0\n   rof\n\nbp    spl #bite+tptr-1, <flag\ntrap  spl -1, <flag  ; The trap, executed by the opponent.\n      spl #4000, }1    ; Count the number of proceses entering here.\ntsrc  jmn.a #0-MAXPROCESSES, #-3  ; When every process is trapped,\n      dat 0, 0  ; they move from the last line (tsrc) to this DAT.\n      dat 0, 0\n\nend boot\n\n"}, {"file": "sonofvain.red", "source": ";redcode-94nop\n;name Son of Vain\n;author Oversby/Pihlaja\n;strategy qscan -> stone/imp\n;assert 1\nload0 z for 0\n        rof\n\nofs equ (-2)                            ; offset boot distances by this much.\n\n; stone constants\nstep    equ     6457                    ; primary step\nhop     equ     3643                    ; decr. ofs from bomb\ndbofs   equ     9                       ; bomb distance from stone\ntgt     equ     2                       ; first mutation target\ntime    equ     2293                    ; bombs before first mutation\nsdist   equ     (2599+ofs)              ; boot distance\n\n; clear constants\ndgate   equ     (dclr-9)\ndwipeofs equ    (-947)                  ; offset of clear trail from stone\nddist   equ     (7328+ofs)              ; boot distance\ndmopa   equ     <2667                   ; mop a-field\n\n; spin constants\nldist   equ     (7426+ofs)              ; boot distance\nldecoy  equ     (5956+ofs)              ; decoy distance\nidist   equ     (7471+ofs)              ; imp trail dist.\n\n; qscan constants\n\na1      equ     3922                    ; factors and scan offsets\na2      equ     1999\nb1      equ     609\nb2      equ     6686\nb3      equ     4763\nc2      equ     2149\nd       equ     5014\n\n; qbomb constants\n\nqrep    equ     13                      ; repeats of bomb loop\nqinc1   equ     7                       ; attack step\nqhop    equ     60                      ; offset of bomb\n\n\n;;-- primary boot\n;;\n\nboot    spl     misc    ,       >b1     ; start secondary boot\nt2      spl     1       ,       >b2     ; t2 = qscan decode table\n        spl     1       ,       >b3\n        mov     <dsrc   ,       <ddst\n        mov     <ssrc   ,       {sdst\n        mov     <lsrc   ,       {ldst\nsdst ddst spl   load0+sdist+4,  load0+ddist+4\nldst    jmp     load0+ldist+4,  <chk_flag\n\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n;;-- imp launcher\n;;\nlsrc\nspin    spl     #1      ,       4       ; the a-field is checked by misc boot.\n        add.a   #2667   ,       1\n        djn.f   spin+idist-ldist-1-2667,<spin-ldist+ldecoy\n        dat     0       ,       0\n\n        dat     0,0\n        dat     0,0\nt3      dat.a   qhop    ,       c2      ; t3 = qscan decode table\n        dat     0,0                     ;      & attack bomb.\n        dat     0,0\n        dat     0,0\n        dat     0,0\n\n;;-- clear\n;;\n\nimp     mov.i   #10     ,       2667\ndb      dat.a   >hop    ,       >1      ; dat bomb for stone\ndmop    dat.a   dmopa   ,       dclr+8-dgate ; dat bomb for clear\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\ndsrc\ndclr    spl     #0      ,       4\n        spl     #0      ,       {dgate\n        mov     dgate+2 ,       >dgate\n        djn.f   -1      ,       >dgate\n\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n;;-- qscan body\n;;\nqscan   seq     qb + d  ,       qb + d + b2\n        jmp     q1\n\n        sne     qb + d * a1,    qb + d * a1 + b2\n        seq     <t1-1   ,       qb + d * (a1-1) + b2    ; t1-1 + a1-1\n        djn.a   q0      ,       {q0                     ; == qb+d*(a1-1)\n\n        sne     qb + d * a2,    qb + d * a2 + b2\n        seq     <t1     ,       qb + d * (a2-1) + b2    ; t1 + a2-1\n        jmp     q0      ,       {q0                     ; == qb+d*(a2-1)\n\n        sne     qb + d * b1,    qb + d * b1 + b1\n        seq     <t2-1   ,       qb + d * (b1-1) + (b1-1); t2-1 + b1-1\n        jmp     q0      ,       {q2                     ; == qb+d*(b1-1)\n\n        sne     qb + d * b3,    qb + d * b3 + b3\n        seq     <t2+1   ,       qb + d * (b3-1) + (b3-1); t2+1 + b3-1\n        jmp     q0      ,       }q2                     ; == qb+d*(b3-1)\n\n        seq     qb + d * (b1-2),qb + d * (b1-2) + (b1-2); must follow the\n        djn     q0      ,       {q2                     ; <t2-1 scan\n\n        sne     qb + d * c2,    qb + d * c2 + b2\n        seq     <t3     ,       qb + d * (c2-1) + b2    ; t3 + c2-1\n        jmp     q0      ,       }q0                     ; == qb+d*(c2-1)\n\n        sne     qb + d * b2,    qb + d * b2 + b2\n        seq     <t2     ,       qb + d * (b2-1) + (b2-1); t2 + b2-1\n                                                        ; == qb+d*(b2-1)\n        jmp     q0      ,       >a1                     ; q0-1 and boot-1\nt1      jmp     boot    ,       >a2                     ; must be dat 0,0's.\n\n;;-- stone\n;;\nspl0\nssrc    ;spl    0       ,       0\nst      spl     0       ,       4\n        mov     -1+dbofs,       @2\n        add     #step   ,       @-1\n        djn.a   @-1     ,       *st+(tgt-hop)-(step*time)\n\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n        dat     0,0\n\n;;-- misc. boot\n;;\n        ; bmbdist: address of stone bomb.\n        ; gatedist: address of clear gate.\n        ; wipedist: address of clear wipe start.\nbmbdist equ     (sdist+dbofs)\ngatedist equ    (ddist+dgate-dclr)\nwipedist equ    (sdist+dwipeofs-ddist+dclr-dgate)\n\nmisc    mov     imp     ,       load0+idist\n        mov     db      ,       load0+bmbdist\npmop    mov     dmop    ,       load0+gatedist+2\n        mov     spl0    ,       {sdst\n        mov     dmop    ,       <pmop\n        mov.x   #wipedist,      <pmop\n        spl     @ddst                   ; start clear.\nchk_flag djn.a  dclr+1  ,       *ldst+4\n        dat     0,0\n\n;;-- qbomb\n;;\n;       dat     0,0                     ; dat be here.\nq0      mul.b   *2      ,       qb\nq1      sne     {t1     ,       @qb\nq2      add.b   t2      ,       qb\n        mov     t3      ,       @qb\nqb      mov     t3      ,       *d\n        sub     #qinc1  ,       qb\n        djn     -3      ,       #qrep\n        jmp     boot\n\n        end     qscan\n\n"}, {"file": "sunset.red", "source": ";redcode-94\n;assert CORESIZE==8000\n;name Sunset\n;author David Moore\n;strategy P^3\n;strategy Recon 2 or paper + stone\n\n;---------\n; Recon 2\n;---------\n\n; Recon 2 looks at pairs of cells that are 6 apart.\n; When something is found, it gets wiped with 14 SPLs like this:\n; ..X.....X.....\n\n; distance between scanned pairs:\nrStep equ 6557   ; overcomes 3, 7, 9, and 11 point imps\n\n; 6557 * 231 = 2667   (2667 *  3 = 1)\n; 6557 *  99 = 1143   (1143 *  7 = 1)\n; 6557 *  77 =  889   ( 889 *  9 = 1)\n; 6557 *  63 = 5091   (5091 * 11 = 1)\n\n; use different boot locations to throw off one-shot scanners\nrPlaceA equ 1282\nrPlaceB equ 6800\n\nrDestB  nop (rPlaceB - rPlaceA), (rPlaceB-rPlaceA)\n\nreconB  add.f rDestB, rDest   ; boot to location B\nreconA  mov  rEnd,   <rDest   ; boot to location A\n        mov {reconA, <rDest\n        mov {reconA, <rDest\n        mov {reconA, <rDest\n        mov {reconA, <rDest\nrSrc    jmn  reconA, {reconA\nrDest   spl  rPlaceA+5, rPlaceA+15\n        mov  2, rDest   ; hide boot pointer\n\n    for 5\n        dat 0, 0\n    rof\n\nrPtr equ (rScan-8)\n\n        dat      19,  19\nrDiff   spl #-rStep, #-rStep\nrWipe   mov   rDiff, >rPtr    ; hit 'em with SPLs\nrW2     mov  *rWipe, >rPtr    ; later, this becomes a DAT clear\n        djn.a rWipe,  rLength\n\nrLoop   sub   rDiff, @rS2\nrScan   sne rStep-1,  rStep-7 ; check a pair\n        sub   rDiff,  rScan\nrS2     seq  *rScan, @rScan   ; check another pair\n        slt.a   #20,  rScan   ; ignore self\nrTimer  djn   rLoop, #4800    ; count down to DAT phase\n\nrLength sub.ba   #0,   #-7     ; set up for SPL wipe\nrTweak  mov.ab @rS2,   @rWipe\nrT2     jmn    *rW2,    rTimer ; when timer expires,\nrEnd    djn.a <rTweak, {rT2    ; go to DAT clear mode\n\n;---------\n; P-space\n;---------\n\n    for 12\n        dat 0,0\n    rof\n\nstorage equ 234\n\nthink   ldp.a  #0,      mtab\n        ldp.ba  2,      table\n        mod.ba *mtab,   table\n        stp.b  *table, #storage\ntable   jmp }0,     724 ; =  80*9 + 4 = 65*11 +  9 = 72*10 + 4\n        jmp paper,  130 ; =  14*9 + 4 = 11*11 +  9 = 13*10 + 0\n        dat reconB, 666 ; =  74*9 + 0 = 60*11 +  6 = 66*10 + 6\n        dat paper,  835 ; =  92*9 + 7 = 75*11 + 10 = 83*10 + 5\n        dat reconA, 448 ; =  49*9 + 7 = 40*11 +  8 = 44*10 + 8\n        dat paper,  857 ; =  95*9 + 2 = 77*11 + 10 = 85*10 + 7\n        dat reconB, 776 ; =  86*9 + 2 = 70*11 +  6 = 77*10 + 6\n        dat paper,  362 ; =  40*9 + 2 = 32*11 + 10 = 36*10 + 2\n        dat reconA, 778 ; =  86*9 + 4 = 70*11 +  8 = 77*10 + 8\n        dat paper,  801 ; =  89*9 + 0 = 72*11 +  9 = 80*10 + 1\n        dat paper,  923 ; = 102*9 + 5 = 83*11 + 10 = 92*10 + 3\nmtab    dat 0,  9\n        dat 0, 11\n        dat 0, 10\n        DAT.F $-52, $778   ; mirror - used by Recon 2\n\n    for 17\n        dat 0,0\n    rof\n\n;---------------\n; paper + stone\n;---------------\n\npStone  spl #2 * 2862, {2 * 2862\n        mov pAmmo, *2\n        add.f pStone, 1    ; <- hit to start core clear\n        mov 4655, 4655 + 2862\npSrcS   jmp -3, pStone\n        dat 0,0\npAmmo   dat }1, >1\n\n; This replicator fills the core with code that can't be run\n; by other replicators.\n\npNext   spl   4200,  {pThis\n        mov  }pThis, }pNext\n        mov   pDat,  >5200\npThis   mov pNext+6, }pNext\n        jmz.f pNext, *pThis\npDat    dat  <2667,  <5334\n;;;     dat      0,   0      ; dat 0,0 must be there after boot\n\nplaceS equ 5300     ; stone boot location\nplaceP equ (placeS + 223)   ; paper boot location\n\npaper   mov >pSrcS, >pDestS\n        spl  2, >3988\n        spl  1, >4191\npSrcP   spl  1,  pNext+6\n        mov >pSrcS,  >pDestS\n        mov <pSrcP,  {pDestP\npDestS  spl @pDestP,  paper+placeS  ; the stone needs 6+6 processes\n        spl @pDestP, >pDestS        ; to work properly\npDestP  djn  paper+placeP+6, #paper+placeS  ; the paper needs 6\n\nend think\n\n"}];
